// src/lib/plattform/validierung.js
//
// Eingaben bereinigen – jede API übernimmt Felder nur über diese Helfer
// (Positivliste statt „alles speichern“). Client- und serverseitig nutzbar.

import { ungueltig } from "./fehler";

const STEUER = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

/** Einzeiliger Text: Steuerzeichen und Zeilenumbrüche raus, gekürzt */
export function text(v, max = 200) {
  if (v === undefined || v === null || typeof v === "object") return "";
  return String(v).replace(STEUER, "").replace(/[\r\n\t]+/g, " ").replace(/\s{2,}/g, " ").trim().slice(0, max);
}

/** Mehrzeiliger Text (Beschreibungen, Nachrichten) */
export function mehrzeilig(v, max = 5000) {
  if (v === undefined || v === null || typeof v === "object") return "";
  return String(v).replace(STEUER, "").replace(/\r\n?/g, "\n").replace(/\n{4,}/g, "\n\n\n").trim().slice(0, max);
}

const EMAIL = /^[^\s@<>()[\]\\,;:"]{1,64}@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/i;

export function email(v) {
  const e = text(v, 190).toLowerCase();
  return EMAIL.test(e) ? e : "";
}

/** Zahl in Grenzen oder null */
export function zahl(v, { min = -Infinity, max = Infinity, stellen } = {}) {
  if (v === undefined || v === null || v === "" || typeof v === "object") return null;
  const n = typeof v === "number" ? v : Number(String(v).replace(/\s/g, "").replace(",", "."));
  if (!Number.isFinite(n) || n < min || n > max) return null;
  return stellen === undefined ? n : Math.round(n * 10 ** stellen) / 10 ** stellen;
}

export function auswahl(v, erlaubt, standard = "") {
  const liste = Array.isArray(erlaubt) ? erlaubt : Object.keys(erlaubt);
  return liste.includes(v) ? v : standard;
}

export function mehrfach(v, erlaubt) {
  const liste = Array.isArray(erlaubt) ? erlaubt : Object.keys(erlaubt);
  return Array.isArray(v) ? [...new Set(v.filter((x) => liste.includes(x)))] : [];
}

export const wahr = (v) => v === true || v === "true" || v === "on" || v === 1;

export function textListe(v, { max = 10, laenge = 160 } = {}) {
  if (!Array.isArray(v)) return [];
  return v.map((x) => text(x, laenge)).filter(Boolean).slice(0, max);
}

/** Datum im Format JJJJ-MM oder JJJJ (geplante Inbetriebnahme) */
export function monat(v) {
  const s = text(v, 7);
  return /^20\d\d(-(0[1-9]|1[0-2]))?$/.test(s) ? s : "";
}

export function plz(v) {
  const s = text(v, 10);
  return /^[0-9A-Za-z -]{3,10}$/.test(s) ? s : "";
}

/** Passwortregeln – liefert Fehlermeldung oder "" */
export function passwortFehler(pw) {
  const p = typeof pw === "string" ? pw : "";
  if (p.length < 10) return "Das Passwort muss mindestens 10 Zeichen lang sein.";
  if (p.length > 200) return "Das Passwort ist zu lang.";
  if (!/[A-Za-zÄÖÜäöüß]/.test(p) || !/[^A-Za-zÄÖÜäöüß]/.test(p)) {
    return "Bitte verwenden Sie Buchstaben und mindestens eine Ziffer oder ein Sonderzeichen.";
  }
  return "";
}

/** Wirft 422, wenn Bedingung nicht erfüllt */
export function pflicht(bedingung, meldung) {
  if (!bedingung) throw ungueltig(meldung);
}

/** Interne Kennungen (z. B. V-26-AB12CD) */
export const kennung = (v) => (/^[A-Z]{1,3}-[0-9A-Z-]{4,40}$/.test(String(v || "")) ? String(v) : "");

/** URL-Slug */
export const slug = (v) => (/^[a-z0-9-]{3,120}$/.test(String(v || "")) ? String(v) : "");
// src/lib/plattform/checkliste.js
//
// Dokumenten-Checklisten: welche Unterlagen je Projektphase bzw. je Fläche erwartet werden.
// Ein Dokument erfüllt einen Punkt, wenn es mit dem Schlüssel des Punkts (Feld `checkliste`)
// hochgeladen wurde. Der Vollständigkeitsgrad der Pflichtpunkte fließt als „Datenraum-Qualität“
// (0–100) in die Börsenkarte ein. Frappe nutzt dieselbe Tabelle (plattform/checkliste.py).
//
// Client- und serverseitig nutzbar (keine Node-Importe).

import { PHASEN } from "@/lib/invest/markt";

const PHASE_IDX = (id) => Math.max(0, PHASEN.findIndex((p) => p.id === id));

/**
 * Projekt-Checkliste. `ab` = Phase, ab der die Unterlage erwartet wird.
 * `ohne` = Projekttypen, für die der Punkt entfällt. `land` = abweichende Bezeichnung je Land.
 */
export const CHECKLISTE_PROJEKT = [
  { id: "pacht", ab: "flaeche", pflicht: true, label: "Pacht- bzw. Nutzungsverträge (geschwärzt)", text: "Flächensicherung für alle Flurstücke inkl. Laufzeit und Verlängerungsoption." },
  { id: "lageplan", ab: "flaeche", pflicht: true, label: "Lageplan mit Flurstücken", text: "Übersichtsplan mit Projektgrenze und Zuwegung." },
  { id: "netzzusage", ab: "netz", pflicht: true, label: "Netzanschlusszusage", text: "Zusage bzw. Reservierung des Netzbetreibers mit Verknüpfungspunkt und Leistung." },
  { id: "aufstellung", ab: "aufstellung", pflicht: true, ohne: ["carport", "dach"], label: "Aufstellungsbeschluss B-Plan", land: { AT: "Einleitung Umwidmung (Grünland-PV)", CH: "Einleitung Nutzungsplanung" }, text: "Beschluss der Gemeinde zur Bauleitplanung bzw. Einleitung des Widmungsverfahrens." },
  { id: "gutachten", ab: "aufstellung", pflicht: true, label: "Fachgutachten", text: "Umwelt, Artenschutz, Blendung, Boden – soweit für das Verfahren gefordert." },
  { id: "satzung", ab: "satzung", pflicht: true, label: "B-Plan-Satzungsbeschluss", land: { AT: "Widmung Grünland-PV / Baubewilligung", CH: "Baubewilligung" }, text: "Rechtskräftiges Planungsrecht." },
  { id: "ertrag", ab: "satzung", pflicht: true, ohne: ["speicher"], label: "Ertragsgutachten", text: "Unabhängiges Ertragsgutachten (P50/P90)." },
  { id: "baugenehmigung", ab: "rtb", pflicht: true, label: "Baugenehmigung & Freigaben", text: "Baugenehmigung bzw. -anzeige und Freigaben des Netzbetreibers." },
  { id: "eeg", ab: "rtb", pflicht: false, ohne: ["speicher"], label: "EEG-Zuschlag bzw. Vermarktung", land: { AT: "EAG-Förderzusage bzw. PPA", CH: "Einmalvergütung bzw. Abnahmevertrag" }, text: "Zuschlag aus der Ausschreibung oder Vermarktungskonzept (PPA) – optional." },
  { id: "betrieb", ab: "cod", pflicht: true, label: "Betriebsdaten & Inbetriebnahme", text: "Inbetriebnahmeprotokoll, Ertragsdaten, laufende Verträge (Wartung, Direktvermarktung)." },
];

/** Flächen-Checkliste (Flächeneigentümer, Landwirte) */
export const CHECKLISTE_FLAECHE = [
  { id: "grundbuch", pflicht: true, label: "Grundbuchauszug", land: { AT: "Grundbuchsauszug" }, text: "Aktueller Auszug für alle Flurstücke (nicht älter als drei Monate)." },
  { id: "flurkarte", pflicht: true, label: "Flurkarte", land: { AT: "Katastralmappe", CH: "Katasterplan" }, text: "Auszug aus dem Liegenschaftskataster mit markierten Flurstücken." },
  { id: "vollmacht", pflicht: true, nurWenn: (f) => f?.eigentum && f.eigentum !== "eigentum", label: "Vollmacht bzw. Zustimmung der Miteigentümer", text: "Nur bei Miteigentum oder Verwaltung erforderlich." },
  { id: "pachtDritter", pflicht: false, label: "Bestehende Pachtverträge Dritter", text: "Falls die Fläche derzeit landwirtschaftlich verpachtet ist – optional." },
];

export const CHECKLISTE_IDS = {
  projekt: CHECKLISTE_PROJEKT.map((x) => x.id),
  flaeche: CHECKLISTE_FLAECHE.map((x) => x.id),
};

function auswerten(punkte) {
  const pflicht = punkte.filter((x) => x.erwartet && x.pflicht);
  const erfuellt = pflicht.filter((x) => x.vorhanden).length;
  return {
    punkte,
    erwartet: pflicht.length,
    erfuellt,
    quote: pflicht.length ? Math.round((erfuellt / pflicht.length) * 100) : 100,
  };
}

function belege(dokumente, id) {
  return (dokumente || []).filter((d) => d.checkliste === id).map((d) => ({ id: d.id, name: d.name, am: d.am }));
}

/** Checkliste eines Projekts; `dokumente` = Metadaten mit Feld `checkliste` */
export function checklisteProjekt(p, dokumente = []) {
  const phase = PHASE_IDX(p?.phase);
  const punkte = CHECKLISTE_PROJEKT.filter((x) => !(x.ohne || []).includes(p?.typ)).map((x) => {
    const d = belege(dokumente, x.id);
    return {
      id: x.id,
      label: x.land?.[p?.land] || x.label,
      text: x.text,
      pflicht: x.pflicht,
      ab: x.ab,
      erwartet: PHASE_IDX(x.ab) <= phase,
      vorhanden: d.length > 0,
      dokumente: d,
    };
  });
  return auswerten(punkte);
}

/** Checkliste einer Fläche */
export function checklisteFlaeche(f, dokumente = []) {
  const punkte = CHECKLISTE_FLAECHE.map((x) => {
    const d = belege(dokumente, x.id);
    const erwartet = x.nurWenn ? !!x.nurWenn(f) : true;
    return { id: x.id, label: x.land?.[f?.land] || x.label, text: x.text, pflicht: x.pflicht, erwartet, vorhanden: d.length > 0, dokumente: d };
  });
  return auswerten(punkte);
}

/** Nur die Kennzahl für die Börsenkarte (öffentlich unkritisch: ein Prozentwert) */
export const datenraumQualitaet = (p, dokumente) => checklisteProjekt(p, dokumente).quote;
// src/lib/plattform/oeffentlich.js
//
// Sichtbarkeitsregeln für Projekte der Börse (Positivliste).
//  - öffentlich:  anonymer Teaser, grobe Region, keine Anbieterdaten
//  - vertraulich: nur für Anbieter, Admin und Investoren mit freigegebenem NDA
// Beide Backends liefern Daten ausschließlich über diese Projektionen aus.

const OEFFENTLICH = [
  "id", "slug", "titel", "typ", "land", "bundesland", "region", "mwp", "mwhSpeicher", "flaecheHa", "phase", "netzanschluss",
  "codGeplant", "preisModus", "preis", "preisProKwp", "beschreibung", "highlights", "status", "veroeffentlichtAm", "demo",
];

/** Öffentlicher Teaser – für Liste und Exposé ohne NDA */
export function projektOeffentlich(p) {
  if (!p) return null;
  const o = {};
  for (const k of OEFFENTLICH) if (p[k] !== undefined) o[k] = p[k];
  o.highlights = Array.isArray(p.highlights) ? p.highlights : [];
  return o;
}

/** Vertrauliche Felder – nur nach NDA-Freigabe */
export const VERTRAULICH_FELDER = {
  gemeinde: "Gemeinde",
  gemarkung: "Gemarkung / Katastralgemeinde",
  flurstuecke: "Flurstücke",
  netzbetreiber: "Netzbetreiber",
  einspeisepunkt: "Einspeisepunkt / Umspannwerk",
  entfernungNetzKm: "Entfernung zum Netzverknüpfungspunkt (km)",
  sicherung: "Flächensicherung (Pacht / Gestattung)",
  planungsrecht: "Planungsrechtlicher Stand",
  ertragKwhKwp: "Spezifischer Ertrag (kWh/kWp)",
  verguetung: "Vergütung / Vermarktung",
  details: "Weitere Angaben",
};

export function projektVertraulich(p) {
  const v = p?.vertraulich || {};
  const o = {};
  for (const k of Object.keys(VERTRAULICH_FELDER)) if (v[k] !== undefined && v[k] !== "") o[k] = v[k];
  return o;
}
// src/lib/plattform/matching.js
//
// Passung Projekt ↔ Suchprofil eines Investors (0–100 Punkte).
// Gewichte: Typ 25, Phase 25, Land 20, Größe 20, Ticket 10.
// Leere Kriterien im Profil zählen als „egal“ (volle Punkte).

import { preisGesamt } from "./format";
import { PHASEN } from "@/lib/invest/markt";
import { LAENDER, PROJEKT_TYPEN } from "./konstanten";

export function matching(projekt, profil) {
  if (!projekt) return { score: 0, gruende: [] };
  const p = profil || {};
  const gruende = [];
  let score = 0;

  // Typ
  if (!p.typen?.length || p.typen.includes(projekt.typ)) {
    score += 25;
    if (p.typen?.length) gruende.push(PROJEKT_TYPEN[projekt.typ] || projekt.typ);
  }

  // Phase – benachbarte Phase gibt halbe Punkte
  if (!p.phasen?.length) score += 25;
  else if (p.phasen.includes(projekt.phase)) {
    score += 25;
    gruende.push(PHASEN.find((x) => x.id === projekt.phase)?.kurz || projekt.phase);
  } else {
    const idx = PHASEN.findIndex((x) => x.id === projekt.phase);
    const nah = p.phasen.some((ph) => Math.abs(PHASEN.findIndex((x) => x.id === ph) - idx) === 1);
    if (nah) score += 12;
  }

  // Land
  if (!p.laender?.length || p.laender.includes(projekt.land)) {
    score += 20;
    if (p.laender?.length) gruende.push(LAENDER[projekt.land] || projekt.land);
  }

  // Größe – bis 25 % außerhalb der Spanne halbe Punkte
  const m = Number(projekt.mwp) || 0;
  const min = Number(p.mwpMin) || 0;
  const max = Number(p.mwpMax) || Infinity;
  if (m >= min && m <= max) {
    score += 20;
    if (p.mwpMin || p.mwpMax) gruende.push("Größe passt");
  } else if (m >= min * 0.75 && m <= max * 1.25) score += 10;

  // Ticket
  const preis = preisGesamt(projekt);
  const tMin = Number(p.ticketMin) || 0;
  const tMax = Number(p.ticketMax) || Infinity;
  if (!p.ticketMin && !p.ticketMax) score += 10;
  else if (preis === null) score += 5; // auf Anfrage – offen
  else if (preis >= tMin && preis <= tMax) {
    score += 10;
    gruende.push("Ticket passt");
  }

  return { score: Math.round(score), gruende };
}

