export function sommerzeitGrenzen(jahr) {
  return { beginn: Date.UTC(jahr, 2, letzterSonntagUtc(jahr, 2), 1), ende: Date.UTC(jahr, 9, letzterSonntagUtc(jahr, 9), 1) };
