}

/** Lokale Wandzeit → UTC. `zweite` = zweites Auftreten in der doppelten Oktober-Stunde. Liefert {ms, art} */
function ortszeitZuUtc(j, mo, t, h, mi, { zweite = false, nurMez = false } = {}) {
  const wand = Date.UTC(j, mo, t, h, mi);
