    eingaben.kwp = kwp;
    const ist = (db.ertraege || []).filter((z) => z.istMwh > 0);
    if (ist.length && kwp) eingaben.ertragKwhKwp = setze("ertragKwhKwp", Math.round((ist.reduce((s, z) => s + z.istMwh, 0) / ist.length / kwp) * 1000), "Datenblatt");
