      einordnung: r.einordnung,
      cfJahr1: Math.round(r.cfJahr1),
      maxKaufpreis: Math.round(r.wert),
    };
  }
  const p50 = entwicklungRechnen(e, e.p50);
  const p90 = entwicklungRechnen(e, e.p90);
  // Max. Kaufpreis (€/kWp), bei dem der EK-IRR im P50-Fall das Ziel erreicht
  let maxKwp = null;
  const irrBei = (preis) => entwicklungRechnen({ ...e, kaufpreisKwp: preis }, e.p50).ekIrr;
  const lo0 = irrBei(0);
  if (lo0 !== null && lo0 >= ziel) {
    let lo = 0;
    let hi = 1500;
    if ((irrBei(hi) ?? -1) >= ziel) maxKwp = hi;
    else {
      for (let i = 0; i < 40; i++) {
        const mid = (lo + hi) / 2;
        if ((irrBei(mid) ?? -1) >= ziel) lo = mid;
        else hi = mid;
      }
      maxKwp = Math.floor(lo);
    }
  }
  const zusammen = (r) => ({
    projektIrr: r.projektIrr,
    ekIrr: r.ekIrr,
    dscrMin: r.dscrMin,
    lcoeCt: r.lcoeCt,
    kapitalwert: Math.round(r.kapitalwert),
    investition: Math.round(r.investition.summe),
    investProKwp: Math.round(r.investProKwp),
    fk: Math.round(r.fk),
    ek: Math.round(r.ek),
    fkBegrenzt: r.fkBegrenzt,
    ertragJahr1Mwh: Math.round(r.ertragJahr1 / 1000),
    amortisation: r.amortisation,
  });
  return {
    modus,
    p50: zusammen(p50),
    p90: zusammen(p90),
    maxKaufpreisKwp: maxKwp,
    maxKaufpreis: maxKwp !== null ? Math.round(maxKwp * e.mwp * 1000) : null,
    kaufpreis: Math.round((e.kaufpreisKwp || 0) * e.mwp * 1000),
    // Bankensicht: Schuldendienstdeckung im P90-Fall
    p90Tragfaehig: p90.dscrMin === null ? null : p90.dscrMin >= 1.0,
  };
}

