      d.capexEurKwp = p.typ === "agri" ? 980 : p.typ === "carport" ? 1350 : 460;
      d.opexEurKwp = 9;
    }
  }
  if (ph >= 4) {
    d.mBaugenehmigung = "2026-06-30";
    d.genehmigungBestandskraft = "ja";
    d.wrTyp = "String-Wechselrichter 350 kVA (Beispiel)";
    d.dinglich = "eingetragen";
    if (pv) {
