      d.eegRealisierungsfrist = "2027-07-01";
    }
  }
  if (ph === 5) {
    d.codDatum = "2019-06-30";
    d.verfuegbarkeitPct = 99.2;
    d.omVertrag = "Vollwartung inkl. Grünpflege bis 2029 (fiktiv)";
