	v.pflicht(len(a.get("eigentuemer") or "") >= 3, "Bitte geben Sie die Eigentümergesellschaft an (ÖkoInvest GmbH oder Projektgesellschaft).")
	if a.get("dienstbarkeit_status") in ("beantragt", "eingetragen"):
